INSERT INTO categories (id, name, description, status) VALUES
    (1, 'Điện thoại', 'Các dòng điện thoại thông minh chính hãng mới nhất', TRUE),
    (2, 'Laptop', 'Máy tính xách tay văn phòng và gaming hiệu năng cao', TRUE),
    (3, 'Máy tính bảng', 'Thiết bị giải trí, học tập và làm việc đồ họa linh hoạt', TRUE),
    (4, 'Tai nghe', 'Tai nghe True Wireless, tai nghe chống ồn và thiết bị âm thanh', TRUE),
    (5, 'Đồng hồ thông minh', 'Smartwatch thể thao, chăm sóc sức khỏe và thời trang', TRUE),
    (6, 'Phụ kiện công nghệ', 'Củ sạc nhanh, chuột máy tính, thẻ nhớ và phụ kiện chính hãng', TRUE)
INSERT INTO products (id, name, description, price, stock, image_url, status, category_id) VALUES
    (1, 'Apple iPhone 16 Pro Max 256GB', 'Điện thoại cao cấp với màn hình lớn, hiệu năng mạnh và hệ thống camera linh hoạt, phù hợp chụp ảnh, quay video và giải trí.\n\nThông số kỹ thuật:\nMàn hình Super Retina XDR OLED 6,9 inch, ProMotion 120Hz; chip Apple A18 Pro; bộ nhớ 256GB; camera sau 48MP chính + 48MP góc siêu rộng + 12MP tele 5x; camera trước 12MP; USB-C; 5G; iOS 18 khi ra mắt; khối lượng khoảng 227g.', 30990000.00, 15, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/42/329149/iphone-16-pro-max-titan-den-0-639175378232922591.jpg', TRUE, 1),
    (2, 'Samsung Galaxy S25 Ultra 256GB 12GB RAM', 'Điện thoại cao cấp có màn hình lớn, camera độ phân giải cao, bút S Pen và các tính năng Galaxy AI.\n\nThông số kỹ thuật:\nMàn hình Dynamic AMOLED 2X 6,9 inch, 120Hz; Snapdragon 8 Elite for Galaxy; RAM 12GB; bộ nhớ 256GB; camera sau 200MP + 50MP góc siêu rộng + 10MP tele 3x + 50MP tele 5x; camera trước 12MP; pin 5000mAh; USB-C; 5G; IP68; Android 15/One UI 7 khi ra mắt; khoảng 218g.', 27490000.00, 12, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/42/361947/samsung-galaxy-s26-blue-1-639077197706721504.jpg', TRUE, 1),
    (3, 'Xiaomi 15 256GB', 'Điện thoại hiệu năng cao với thiết kế gọn, camera hợp tác Leica và sạc nhanh, phù hợp nhu cầu chụp ảnh và sử dụng đa nhiệm.\n\nThông số kỹ thuật:\nMàn hình AMOLED khoảng 6,36 inch, tối đa 120Hz; Snapdragon 8 Elite; RAM 12GB (tùy phiên bản); bộ nhớ 256GB; hệ thống camera sau ba camera 50MP; camera trước 32MP; pin và công suất sạc tùy phiên bản thị trường; USB-C; 5G; Android/HyperOS theo bản phát hành.', 18990000.00, 20, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/42/360307/xiaomi-redmi-note-15-pro-xanh-1-639032525099082700.jpg', TRUE, 1),
    (4, 'Apple iPhone 18 128GB', 'Điện thoại gọn nhẹ với chip A18, camera Fusion 48MP và trải nghiệm hệ sinh thái Apple cho nhu cầu hằng ngày.\n\nThông số kỹ thuật:\nMàn hình Super Retina XDR OLED 6,1 inch, 60Hz; chip Apple A18; bộ nhớ 128GB; camera sau 48MP Fusion + 12MP góc siêu rộng; camera trước 12MP; USB-C; 5G; Face ID; iOS 18 khi ra mắt; khoảng 170g.', 18990000.00, 18, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/42/370980/iphone-18-pro-burgundy-1-639246114764541080.jpg', TRUE, 1),
    (5, 'Samsung Galaxy S25 256GB 12GB RAM', 'Điện thoại cao cấp nhỏ gọn với màn hình 120Hz, hiệu năng mạnh và các tính năng Galaxy AI.\n\nThông số kỹ thuật:\nMàn hình Dynamic AMOLED 2X 6,2 inch, 120Hz; Snapdragon 8 Elite for Galaxy; RAM 12GB; bộ nhớ 256GB; camera sau 50MP + 12MP góc siêu rộng + 10MP tele 3x; camera trước 12MP; pin 4000mAh; USB-C; 5G; IP68; Android 15/One UI 7 khi ra mắt; khoảng 162g.', 17690000.00, 16, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/42/333363/samsung-galaxy-s25-xanh-2-638747827770343042.jpg', TRUE, 1),
    (6, 'ASUS Vivobook 15 X1504VA Core i5', 'Laptop phổ thông cho học tập và văn phòng, có màn hình 15,6 inch và cấu hình hướng đến công việc hằng ngày.\n\nThông số kỹ thuật:\nCPU Intel Core i5 thế hệ 13 (tùy SKU); đồ họa Intel tích hợp; RAM thường 8GB/16GB tùy cấu hình; SSD NVMe 512GB tùy SKU; màn hình 15,6 inch Full HD; Wi‑Fi; Bluetooth; webcam; Windows tùy gói bán; khối lượng khoảng 1,7kg. Phải xác nhận mã SKU trước khi chốt.', 14990000.00, 10, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/44/369758/asus-vivobook-go-15-x1504ma-bq893w-core-3-304-8gb-512gb-full-hd-win11-1-639211905724656906.jpg', TRUE, 2),
    (7, 'Acer Aspire 5 A515 Core i5', 'Laptop phục vụ học tập, làm việc văn phòng và đa nhiệm cơ bản với màn hình rộng và SSD.\n\nThông số kỹ thuật:\nCPU Intel Core i5 tùy thế hệ/SKU; đồ họa Intel Iris Xe hoặc UHD tùy cấu hình; RAM 8GB/16GB tùy SKU; SSD 512GB thường gặp; màn hình 15,6 inch Full HD; Wi‑Fi; Bluetooth; cổng USB-A/USB-C/HDMI tùy bản; Windows tùy gói; khoảng 1,7–1,8kg.', 15990000.00, 8, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/44/330167/acer-aspire-5-a515-58p-774r-i7-nxkhjsv005-3-638648695329312043.jpg', TRUE, 2),
    (8, 'Lenovo IdeaPad Slim 3 15IRH10', 'Laptop gọn nhẹ cho sinh viên và nhân viên văn phòng, phù hợp xử lý tài liệu, học trực tuyến và đa nhiệm.\n\nThông số kỹ thuật:\nCPU Intel Core H-series tùy cấu hình; đồ họa tích hợp; RAM và SSD tùy SKU; màn hình khoảng 15,3–15,6 inch tùy phiên bản; webcam; Wi‑Fi; Bluetooth; USB-C/USB-A/HDMI tùy SKU; hệ điều hành tùy gói bán. Cần đối chiếu mã máy cụ thể.', 15990000.00, 9, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/44/334444/lenovo-ideapad-slim-3-15irh10-i7-83k1000jvn-1-638756561663160755.jpg', TRUE, 2),
    (9, 'Apple MacBook Air 13 inch M3 256GB', 'Laptop mỏng nhẹ, hoạt động yên tĩnh với chip Apple silicon, phù hợp học tập, văn phòng và sáng tạo nội dung nhẹ.\n\nThông số kỹ thuật:\nMàn hình Liquid Retina 13,6 inch; chip Apple M3; bộ nhớ SSD 256GB; RAM thống nhất tùy cấu hình bán; camera 1080p; MagSafe 3; hai cổng Thunderbolt/USB 4; Wi‑Fi; Bluetooth; macOS; pin theo công bố Apple; khối lượng khoảng 1,24kg.', 23990000.00, 7, 'https://cdn.tgdd.vn/Products/Images/44/322612/macbook-air-13-inch-m3-2024-1-1.jpg', TRUE, 2),
    (10, 'HP 15s Core i5 512GB SSD', 'Laptop văn phòng phổ thông có màn hình lớn và ổ SSD, phù hợp làm bài tập, họp trực tuyến và công việc hằng ngày.\n\nThông số kỹ thuật:\nCPU Intel Core i5 tùy thế hệ/SKU; đồ họa tích hợp; RAM thường 8GB/16GB tùy cấu hình; SSD 512GB tùy SKU; màn hình 15,6 inch Full HD tùy bản; webcam; Wi‑Fi; Bluetooth; cổng kết nối tùy model; Windows tùy gói; khoảng 1,6–1,8kg.', 14990000.00, 8, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/44/365608/hp-240r-g9-core-5-120u-c40lgat-1-639116909181716925.jpg', TRUE, 2),
    (11, 'Apple iPad Air 11 inch M2 Wi‑Fi 128GB', 'Máy tính bảng mỏng nhẹ cho học tập, ghi chú, giải trí và sáng tạo nội dung với hỗ trợ phụ kiện tương thích.\n\nThông số kỹ thuật:\nMàn hình Liquid Retina 11 inch; chip Apple M2; bộ nhớ 128GB; camera sau 12MP; camera trước 12MP bố trí cạnh ngang; USB-C; Wi‑Fi; Touch ID; hỗ trợ Apple Pencil tương thích; iPadOS; khối lượng khoảng 462g đối với bản Wi‑Fi.', 14990000.00, 10, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/522/363418/ipad-air-m4-11-inch-wifi-xam-0-639176442561577028.jpg', TRUE, 3),
    (12, 'Apple iPad 10 10.9 inch Wi‑Fi 64GB', 'Máy tính bảng dành cho học tập và giải trí, có màn hình lớn, camera trước cạnh ngang và cổng USB-C.\n\nThông số kỹ thuật:\nMàn hình Liquid Retina 10,9 inch; chip A14 Bionic; bộ nhớ 64GB; camera sau 12MP; camera trước 12MP Ultra Wide; USB-C; Wi‑Fi; Touch ID; hỗ trợ Apple Pencil thế hệ 1 qua bộ chuyển đổi phù hợp; iPadOS; khoảng 477g bản Wi‑Fi.', 8490000.00, 14, 'https://cdn.tgdd.vn/Products/Images/522/295452/ipad-10-5g-hong-1.jpg', TRUE, 3),
    (13, 'Samsung Galaxy Tab S10 FE Wi‑Fi 128GB', 'Máy tính bảng Android cho học tập và làm việc, hỗ trợ bút S Pen và màn hình kích thước lớn.\n\nThông số kỹ thuật:\nMàn hình khoảng 10,9 inch; chipset Exynos 1580; RAM/bộ nhớ tùy bản, cấu hình tham khảo 8GB/128GB; camera sau 13MP; camera trước 12MP; pin khoảng 8000mAh; USB-C; Wi‑Fi; hỗ trợ S Pen; IP68 trên thiết bị và bút theo công bố Samsung; Android/One UI theo phiên bản.', 11990000.00, 10, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/522/322131/samsung-galaxy-tab-s10-plus-sliver-4-638640919802337984.jpg', TRUE, 3),
    (14, 'Xiaomi Redmi Pad Pro 8GB 256GB', 'Máy tính bảng màn hình lớn, tần số quét cao và pin dung lượng lớn, phù hợp xem phim, học tập và giải trí.\n\nThông số kỹ thuật:\nMàn hình LCD 12,1 inch 2.5K, tối đa 120Hz; Snapdragon 7s Gen 2; RAM 8GB; bộ nhớ 256GB; camera sau 8MP; camera trước 8MP; pin 10000mAh; sạc 33W; USB-C; Wi‑Fi; HyperOS dựa trên Android.', 7990000.00, 12, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/522/339207/xiaomi-redmi-pad-2-4g-xam-12-638890346892960318.jpg', TRUE, 3),
    (15, 'Lenovo Tab M11 8GB 128GB', 'Máy tính bảng Android phục vụ học tập, đọc tài liệu và giải trí cơ bản với màn hình 11 inch.\n\nThông số kỹ thuật:\nMàn hình IPS LCD 11 inch, 90Hz; MediaTek Helio G88; RAM/bộ nhớ tùy thị trường, cấu hình tham khảo 8GB/128GB; camera sau 8MP; camera trước 8MP; pin khoảng 7040mAh; USB-C; Wi‑Fi; hỗ trợ bút trên phiên bản tương thích; Android theo bản phát hành.', 4990000.00, 15, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/522/368516/lenovo-idea-tab-4gb-xam-2-639229892356418443.jpg', TRUE, 3),
    (16, 'Apple AirPods Pro 2 USB‑C', 'Tai nghe không dây có chống ồn chủ động, chế độ xuyên âm và hộp sạc USB-C, phù hợp nghe nhạc và gọi điện.\n\nThông số kỹ thuật:\nDriver tùy chỉnh; chống ồn chủ động; chế độ xuyên âm; âm thanh thích ứng và nhận biết cuộc hội thoại tùy thiết bị/phần mềm; điều khiển cảm ứng; Bluetooth; hộp sạc USB-C; kháng bụi/nước theo tiêu chuẩn công bố; thời lượng pin phụ thuộc chế độ sử dụng.', 4990000.00, 20, 'https://cdn.tgdd.vn/Products/Images/54/315014/tai-nghe-bluetooth-airpods-pro-2nd-gen-usb-c-charge-apple-1.jpg', TRUE, 4),
    (17, 'Samsung Galaxy Buds3 Pro', 'Tai nghe true wireless cao cấp với chống ồn chủ động, âm thanh độ phân giải cao tương thích và tích hợp hệ sinh thái Galaxy.\n\nThông số kỹ thuật:\nThiết kế in-ear; driver hai đường tiếng; chống ồn chủ động; Adaptive EQ/ANC; Bluetooth; điều khiển cảm ứng; hộp sạc; khả năng kháng nước theo công bố; một số tính năng yêu cầu thiết bị Samsung Galaxy tương thích.', 4490000.00, 16, 'https://cdn.tgdd.vn/Products/Images/54/327554/tai-nghe-bluetooth-true-wireless-samsung-galaxy-buds-3-pro-r630n-xam-1.jpg', TRUE, 4),
    (18, 'Sony WF‑1000XM5', 'Tai nghe không dây chống ồn cao cấp, hỗ trợ âm thanh chất lượng cao và nhiều tính năng tùy chỉnh qua ứng dụng.\n\nThông số kỹ thuật:\nTai nghe in-ear true wireless; chống ồn chủ động; bộ xử lý và driver theo thiết kế Sony; Bluetooth; hỗ trợ codec tùy thiết bị; microphone tích hợp; sạc USB-C và sạc không dây cho hộp; kháng nước IPX4; thời lượng pin tùy chế độ.', 5290000.00, 9, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/54/313700/tai-nghe-bluetooth-true-wireless-sony-wf1000xm5-hong-1-638633925273870359.jpg', TRUE, 4),
    (19, 'JBL Tune 770NC', 'Tai nghe chụp tai không dây có chống ồn thích ứng, thiết kế gập gọn và thời lượng pin dài.\n\nThông số kỹ thuật:\nThiết kế over-ear; driver 40mm; Adaptive Noise Cancelling; Bluetooth; microphone tích hợp; cổng USB-C; hỗ trợ kết nối đa điểm tùy firmware; thời lượng pin công bố lên đến khoảng 70 giờ khi tắt ANC; khối lượng khoảng 232g.', 2190000.00, 18, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800', TRUE, 4),
    (20, 'Soundcore Life Q30', 'Tai nghe chụp tai không dây có chống ồn nhiều chế độ và pin lâu, phù hợp học tập, làm việc và di chuyển.\n\nThông số kỹ thuật:\nThiết kế over-ear; driver 40mm; chống ồn chủ động với các chế độ tùy chỉnh; Bluetooth; microphone tích hợp; USB-C; có thể dùng dây 3,5mm tùy cấu hình; thời lượng pin phụ thuộc ANC và âm lượng.', 1390000.00, 20, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/54/364925/tai-nghe-bluetooth-true-wireless-havit-life-t1-hong-1-639161663227897086.jpg', TRUE, 4),
    (21, 'Apple Watch Series 10 GPS 42mm', 'Đồng hồ thông minh hỗ trợ theo dõi hoạt động, thông báo và các tính năng sức khỏe, phù hợp người dùng iPhone.\n\nThông số kỹ thuật:\nVỏ 42mm; màn hình Retina Always-On OLED LTPO; chip S10; GPS; cảm biến nhịp tim và cảm biến sức khỏe theo cấu hình; theo dõi giấc ngủ và hoạt động; chống nước theo công bố Apple; watchOS; chỉ tương thích iPhone phù hợp.', 9990000.00, 8, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/7077/371219/apple-watch-series-12-gps-46mm-vien-nhom-day-silicone-den-1-639246692345321374.jpg', TRUE, 5),
    (22, 'Samsung Galaxy Watch7 44mm Bluetooth', 'Đồng hồ thông minh Android có GPS, theo dõi vận động và các chỉ số sức khỏe, tích hợp hệ sinh thái Samsung Galaxy.\n\nThông số kỹ thuật:\nMàn hình Super AMOLED khoảng 1,5 inch trên bản 44mm; chip Exynos W1000; RAM 2GB; bộ nhớ 32GB; GPS; cảm biến BioActive; Wear OS với One UI Watch; pin khoảng 425mAh; chống nước/bụi theo chuẩn công bố; tương thích Android, một số tính năng phụ thuộc điện thoại.', 5990000.00, 10, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/7077/340067/samsung-galaxy-watch8-lte-44mm-xam-1-638878306043919194.jpg', TRUE, 5),
    (23, 'Huawei Watch GT 5 46mm', 'Đồng hồ thông minh thiên về thời lượng pin và theo dõi luyện tập, phù hợp người dùng muốn thiết kế thể thao.\n\nThông số kỹ thuật:\nMàn hình AMOLED khoảng 1,43 inch; GPS; cảm biến nhịp tim và SpO₂; theo dõi giấc ngủ, vận động và nhiều môn thể thao; Bluetooth; hệ điều hành HarmonyOS; thời lượng pin phụ thuộc cách dùng; tương thích Android/iOS với giới hạn tính năng tùy hệ điều hành.', 4690000.00, 12, 'https://cdn2.fptshop.com.vn/unsafe/512x0/filters:format(webp):quality(75)/huawei_watch_gt_5_46mm_den_1_1c13288167.jpg', TRUE, 5),
    (24, 'Xiaomi Smart Band 9 Pro', 'Vòng đeo thông minh có màn hình lớn, GPS tích hợp và nhiều chế độ luyện tập, phù hợp theo dõi vận động hằng ngày.\n\nThông số kỹ thuật:\nMàn hình AMOLED khoảng 1,74 inch; GPS tích hợp; cảm biến nhịp tim, SpO₂, giấc ngủ; nhiều chế độ thể thao; chống nước theo công bố; kết nối Bluetooth; thời lượng pin tùy cách sử dụng; ứng dụng quản lý trên điện thoại.', 1590000.00, 20, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/7077/332404/mi-band-9-pro-hong-hc-1-638687655038773782.jpg', TRUE, 5),
    (25, 'Garmin Forerunner 165', 'Đồng hồ GPS thể thao dành cho người chạy bộ, cung cấp dữ liệu luyện tập, nhịp tim và theo dõi hoạt động.\n\nThông số kỹ thuật:\nMàn hình AMOLED; GPS đa hệ thống; cảm biến nhịp tim cổ tay; theo dõi giấc ngủ và hoạt động; hồ sơ chạy bộ và luyện tập; Bluetooth; Garmin Connect; thời lượng pin phụ thuộc chế độ GPS và sử dụng; kích thước/phiên bản cần xác nhận khi nhập hàng.', 5990000.00, 7, 'https://cdn.tgdd.vn/Products/Images/7077/322848/garmin-forerunner-165-den-1.jpg', TRUE, 5),
    (26, 'Apple 20W USB‑C Power Adapter', 'Bộ tiếp hợp nguồn USB-C nhỏ gọn để sạc iPhone, iPad và các thiết bị tương thích hỗ trợ sạc USB-C.\n\nThông số kỹ thuật:\nCông suất tối đa 20W; đầu ra USB-C; hỗ trợ sạc nhanh với thiết bị tương thích; không kèm cáp trong nhiều gói bán; cần dùng cáp và thiết bị tương thích; thông số điện đầu vào theo nhãn sản phẩm.', 490000.00, 30, 'https://cdn.tgdd.vn/Products/Images/9499/230315/adapter-sac-type-c-20w-cho-iphone-ipad-apple-mhje3-1.jpg', TRUE, 6),
    (27, 'Anker 323 Charger 33W USB‑C', 'Củ sạc USB-C công suất cao cho điện thoại và thiết bị tương thích, thiết kế nhỏ gọn để mang theo.\n\nThông số kỹ thuật:\nCông suất tối đa khoảng 33W tùy phiên bản; cổng USB-C; hỗ trợ các chuẩn sạc nhanh tương thích; cơ chế bảo vệ an toàn theo công bố hãng; cần kiểm tra mã model và chuẩn phích cắm của bản phân phối.', 490000.00, 25, 'https://cdn.tgdd.vn/Products/Images/9499/324952/adapter-sac-3-cong-usb-type-c-iq3-100w-anker-a2145-1.jpg', TRUE, 6),
    (28, 'Samsung 25W USB‑C Power Adapter', 'Củ sạc USB-C 25W cho các thiết bị Samsung và thiết bị tương thích với chuẩn sạc nhanh hỗ trợ.\n\nThông số kỹ thuật:\nCông suất tối đa 25W; cổng USB-C; hỗ trợ USB Power Delivery/PPS tùy model; bảo vệ quá dòng/quá áp theo công bố; cáp có thể bán riêng; kiểm tra mã EP-TA800 hoặc mã tương ứng trước khi nhập.', 350000.00, 30, 'https://cdnv2.tgdd.vn/mwg-static/tgdd/Products/Images/57/369351/pin-sac-du-phong-10000mah-type-c-pd-25w-samsung-eb-p3401-1-639202293308430961.jpg', TRUE, 6),
    (29, 'Logitech Pebble Mouse 2 M350s', 'Chuột không dây nhỏ gọn, thiết kế tối giản, phù hợp laptop, học tập và làm việc văn phòng.\n\nThông số kỹ thuật:\nChuột không dây; kết nối Bluetooth Low Energy và đầu thu Logi Bolt tùy gói bán; nút giữa có thể tùy chỉnh qua phần mềm tương thích; pin AA; tương thích nhiều hệ điều hành; màu sắc tùy phiên bản.', 590000.00, 20, 'https://resource.logitech.com/w_544,h_466,ar_7:6,c_pad,q_auto,f_auto,dpr_1.0/d_transparent.gif/content/dam/logitech/en/products/mice/pebble-mouse-2-m350s/2026-refresh/gallery/pebble-mouse-2-m350s-tonal-rose-top-angle-gallery-1.png', TRUE, 6),
    (30, 'SanDisk Ultra microSDXC 256GB', 'Thẻ nhớ microSDXC 256GB giúp mở rộng dung lượng lưu trữ cho thiết bị tương thích như điện thoại, camera và máy tính bảng.\n\nThông số kỹ thuật:\nDung lượng danh nghĩa 256GB; định dạng microSDXC; tốc độ và chuẩn hiệu năng tùy phiên bản cụ thể; thường kèm adapter SD tùy gói; cần kiểm tra mã sản phẩm, tốc độ đọc/ghi và tính tương thích trước khi nhập.', 490000.00, 25, 'https://cdn2.cellphones.com.vn/insecure/rs:fill:0:358/q:90/plain/https://cellphones.com.vn/media/catalog/product/t/h/the-nho-microsdhc-sandisk-ultra-a1-256gb-150mbs_1.png', TRUE, 6);
