    name = VALUES(name),
    description = VALUES(description),
    status = VALUES(status);

-- 2. Xóa dữ liệu sản phẩm cũ để nhập đủ chuẩn 30 sản phẩm
DELETE FROM products;
ALTER TABLE products AUTO_INCREMENT = 1;

